function tickex_site_url($base,$eventSlug=''){return $eventSlug===''?$base:$base.(strpos($base,'?')===false?'?':'&').'event='.rawurlencode($eventSlug);}
function tickex_site_external_url($value){$value=trim((string)$value);return $value===''?'':(preg_match('~^https?://~i',$value)?$value:'https://'.$value);}
function tickex_site_whatsapp($value){$value=trim((string)$value);if($value===''||preg_match('~^https?://~i',$value))return $value;$digits=preg_replace('/\D+/','',$value);return $digits!==''?'https://wa.me/'.$digits:'';}
function tickex_site_flyer($event){$file=isset($event['flyer_filename'])?str_replace('\\','/',trim((string)$event['flyer_filename'])):'';if($file===''||strpos($file,'..')!==false||preg_match('~^https?://~i',$file))return '';$full=__DIR__.'/'.ltrim($file,'/');return is_file($full)?ltrim($file,'/'):'';}
function tickex_site_checkout($siteSlug,$event){$id=isset($event['id'])?(int)$event['id']:0;if($id<=0)return '#';$eventSlug=isset($event['slug'])?tickex_organizer_site_slug($event['slug']):'';$ref=($siteSlug!==''?$siteSlug:'tickex').'-'.($eventSlug!==''?$eventSlug:$id).'-'.time().'-'.substr(sha1(uniqid('',true)),0,8);$query=array('event'=>$id,'concept'=>$eventSlug!==''?$eventSlug:'evento-'.$id,'ref'=>$ref);if(isset($_GET['aff'])&&trim((string)$_GET['aff'])!=='')$query['aff']=(string)$_GET['aff'];return 'checkout_totalcoin.php?'.http_build_query($query);}
function tickex_site_date($event){$from=isset($event['fecha_desde'])?trim((string)$event['fecha_desde']):'';$to=isset($event['fecha_hasta'])?trim((string)$event['fecha_hasta']):'';if($from===''&&$to==='')return 'Fecha a confirmar';$out=$from!==''?date('d/m/Y · H:i',strtotime($from)):'';if($to!==''&&$to!==$from)$out.=($out!==''?' — ':'').date('d/m/Y · H:i',strtotime($to));return $out;}
