rgin:0;color:var(--muted);font-size:clamp(16px,2vw,19px)}.section{padding:24px 0 70px}.section-head{display:flex;align-items:end;justify-content:space-between;gap:18px;margin-bottom:20px}.section-head h2{margin:0}.section-head p{margin:5px 0 0;color:var(--muted)}.event-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.event-card{display:flex;flex-direction:column;overflow:hidden;border:1px solid var(--line);border-radius:22px;background:var(--panel);box-shadow:0 22px 60px rgba(0,0,0,.18)}.event-image,.event-placeholder{aspect-ratio:4/3;width:100%;object-fit:cover;background:linear-gradient(135deg,var(--primary),#0c1020)}.event-placeholder{display:grid;place-items:center;color:var(--accent);font-weight:900;letter-spacing:.1em}.event-body{display:flex;flex:1;flex-direction:column;padding:19px}.event-body h3{margin:0;font-size:20px;line-height:1.18}.event-date{margin:9px 0 18px;color:var(--muted);font-size:13px}.event-actions{display:flex;gap:8px;margin-top:auto}.event-actions .button{flex:1}.empty{padding:45px 24px;text-align:center;border:1px dashed var(--line);border-radius:22px;color:var(--muted)}.detail{display:grid;grid-template-columns:minmax(280px,.75fr) minmax(0,1.25fr);gap:28px;padding:25px;border:1px solid var(--line);border-radius:26px;background:var(--panel)}.detail img,.detail .event-placeholder{width:100%;border-radius:18px;aspect-ratio:4/3;object-fit:cover}.detail h2{margin:7px 0}.contact{display:flex;flex-wrap:wrap;gap:8px;align-items:center;padding:20px;border:1px solid var(--line);border-radius:20px;background:rgba(255,255,255,.025)}footer{padding:34px 0;border-top:1px solid var(--line);color:var(--muted)}.footer-inner{display:flex;justify-content:space-between;gap:24px;align-items:flex-start}.footer-links{display:flex;gap:15px;flex-wrap:wrap}.powered{font-weight:800;color:#d8dbea}@media(max-width:900px){.event-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.detail{grid-template-columns:1fr}}@media(max-width:620px){.shell{width:min(100% - 28px,1180px)}.topbar-inner{min-height:66px}.top-actions .link{display:none}.brand img{height:36px;max-width:135px}.hero{padding:48px 0 32px}h1{font-size:clamp(39px,14vw,58px)}.event-grid{grid-template-columns:1fr}.event-card{border-radius:18px}.event-actions{flex-direction:column}.button{width:100%}.section{padding-bottom:50px}.section-head,.footer-inner{align-items:flex-start;flex-direction:column}.detail{padding:15px;border-radius:20px}.contact .button{width:auto;flex:1}}</style></head><body>
